/**
 * Stub of `@deepseek-ai/dsh-compaction` — the seam the doctor overrides.
 *
 * `toolPairingBalancedBefore/After` take a **surface seq** and delegate to
 * `session.__balance.before/after` so a test can shape the balance landscape.
 * Both throw when asked about an unknown seq, exactly like the real helpers.
 */

export class CompactionEngine {}

export class ManualCompactionError extends Error {
  constructor(code, message, options = {}) {
    super(message);
    this.name = "ManualCompactionError";
    this.code = code;
    if (options.cause !== undefined) this.cause = options.cause;
  }
}

function ask(session, seq, side) {
  const fn = session?.__balance?.[side];
  if (typeof fn !== "function") return true;
  if (Number.isFinite(seq) === false) throw new Error(`tool-pairing balance: surface seq ${seq} not found`);
  return fn(seq) === true;
}

export function toolPairingBalancedBefore(session, seq) {
  return ask(session, seq, "before");
}

export function toolPairingBalancedAfter(session, seq) {
  return ask(session, seq, "after");
}

export function compactCheckpointSource() {
  return undefined;
}

export function isCompactCheckpointSource() {
  return false;
}

export default {
  CompactionEngine,
  ManualCompactionError,
  toolPairingBalancedBefore,
  toolPairingBalancedAfter,
  compactCheckpointSource,
  isCompactCheckpointSource,
};
